text:
.tab-line {
  block-size: 2px;
  margin-block-start: 3px;
  margin-inline: 3px;
  border-radius: 3px;

  &[selected] {
    background-color: var(--tabline-color);
  }
}

.tab-background {
  background-clip: padding-box;

  &[selected] {
    background-color: var(--toolbar-background-color);
    background-repeat: repeat-x;
  }
